{
  "name": "@alessiods/openrouter-mask",
  "version": "1.0.0",
  "description": "OpenCode plugin that masks your requests as Hermes Agent on OpenRouter. Spoofs HTTP-Referer, X-OpenRouter-Title, and X-OpenRouter-Categories headers.",
  "keywords": [
    "opencode-plugin",
    "opencode",
    "openrouter",
    "hermes-agent",
    "nousresearch",
    "mask",
    "spoof"
  ],
  "license": "MIT",
  "author": {
    "name": "Alessio DS",
    "url": "https://github.com/alessio-ds"
  },
  "homepage": "https://github.com/alessio-ds/openrouter-mask",
  "repository": {
    "type": "git",
    "url": "git+https://github.com/alessio-ds/openrouter-mask.git"
  },
  "bugs": {
    "url": "https://github.com/alessio-ds/openrouter-mask/issues"
  },
  "main": ".opencode/plugins/openrouter-mask.mjs",
  "exports": {
    ".": ".opencode/plugins/openrouter-mask.mjs",
    "./plugin": ".opencode/plugins/openrouter-mask.mjs"
  },
  "files": [
    ".opencode/",
    "LICENSE",
    "README.md"
  ],
  "publishConfig": {
    "access": "public"
  }
}
